:root {
  --ink: #20262b;
  --slate: #53616a;
  --muted: #859198;
  --paper: #fffdf7;
  --line: #d9deda;
  --mist: #edf1ee;
  --lime: #b9de55;
  --mint: #dff0ba;
  --orange: #f28a46;
}

.soundboard {
  width: 500px;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px solid var(--ink);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.board-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  border-bottom: 1px solid var(--ink);
  background: var(--mist);
}

.brand {
  display: flex;
  align-items: center;
  gap: 9px;
}

.brand-mark {
  display: grid;
  width: 26px;
  height: 26px;
  place-items: center;
  border-radius: 50%;
  background: var(--ink);
  color: var(--lime);
  font-size: 17px;
}

.brand-copy,
.cue-copy {
  display: flex;
  flex-direction: column;
}

.eyebrow,
.panel-kicker {
  margin: 0;
  color: var(--slate);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1.1px;
  line-height: 1.2;
}

.board-name {
  margin: 2px 0 0;
  font-size: 15px;
  font-weight: 800;
  line-height: 1;
}

.live-badge {
  border-radius: 99px;
  background: var(--orange);
  padding: 5px 8px;
  color: var(--paper);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .7px;
}

.stage-grid {
  display: grid;
  grid-template-columns: 1.2fr .8fr;
}

.cue-panel {
  padding: 13px 14px 12px;
  border-right: 1px solid var(--line);
}

.scene-title {
  margin: 3px 0 9px;
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -.4px;
  line-height: 1.1;
}

.cue-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.cue-item {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 31px;
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 4px 7px;
}

.active-cue {
  border-color: var(--ink);
  background: var(--mint);
}

.cue-dot {
  width: 8px;
  height: 8px;
  flex: 0 0 auto;
  border-radius: 50%;
}

.dot-ready { background: var(--muted); }
.dot-live { background: var(--orange); }
.dot-next { background: var(--lime); }

.cue-name {
  font-size: 12px;
  font-weight: 800;
  line-height: 1.15;
}

.cue-note {
  margin-top: 1px;
  color: var(--slate);
  font-size: 10px;
  line-height: 1.15;
}

.cue-time {
  margin-left: auto;
  color: var(--slate);
  font-size: 10px;
  font-weight: 700;
}

.mix-panel {
  display: flex;
  flex-direction: column;
  padding: 13px 12px 12px;
  background: var(--paper);
}

.mix-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.mix-value {
  color: var(--slate);
  font-size: 11px;
  font-weight: 800;
}

.meter-stack {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin: 12px 0 13px;
}

.meter-row {
  display: grid;
  grid-template-columns: 12px 1fr;
  align-items: center;
  gap: 6px;
}

.meter-label {
  color: var(--slate);
  font-size: 10px;
  font-weight: 800;
}

.meter-track {
  display: block;
  height: 7px;
  overflow: hidden;
  border-radius: 99px;
  background: var(--mist);
}

.meter-fill {
  display: block;
  height: 100%;
  border-radius: inherit;
}

.fill-rain { width: 78%; background: var(--lime); }
.fill-steps { width: 48%; background: var(--orange); }
.fill-air { width: 63%; background: var(--slate); }

.controls {
  display: flex;
  gap: 6px;
  margin-top: auto;
}

.cue-button,
.arm-button {
  flex: 1;
  border: 1px solid var(--ink);
  border-radius: 5px;
  padding: 6px 4px;
  font-size: 10px;
  font-weight: 800;
}

.cue-button {
  background: var(--paper);
  color: var(--ink);
}

.arm-button {
  background: var(--ink);
  color: var(--lime);
}

.board-footer {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 8px 14px;
  border-top: 1px solid var(--ink);
  background: var(--ink);
  color: var(--paper);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .7px;
}

.footer-separator { color: var(--lime); }
.footer-time { margin-left: auto; color: var(--lime); }
